from packaging.utils import canonicalize_name, InvalidName


def canonicalize_package_name(name: str, validate: bool = False) -> str:
    """Normalize a Python package or extra name to its canonical form. name: The name to normalize. validate: Check whether the name is a valid distribution name. >>> canonicalize_package_name('Django') 'django'"""
