def version_range_intersection(left_specifier: str, right_specifier: str) -> str:
    """Find the intersection of two version ranges using the '&' operator. left_specifier: A version specifier string for the left range, right_specifier: A version specifier string for the right range. Example: version_range_intersection('>=1.0,<2.0', '>=1.5,<2.5') -> '>=1.5,<2.0'."""
    try:
        left_range = SpecifierSet(left_specifier).to_range()
        right_range = SpecifierSet(right_specifier).to_range()
        intersection = left_range & right_range
        return str(intersection.to_specifier_set())
    except Exception as e:
        raise ValueError(f"Invalid version range specification: {e}")
