def specifier_set_contains(version: str, specifiers: str) -> bool:
    """Check if a version is contained within a specifier set using the 'in' operator. version: A version string to check against the specifier set, e.g. '3.1.0' -> true. specifiers: A string representation of version specifiers (e.g., '>=3.0,!=3.1')"""
    try:
        specifier_set = SpecifierSet(specifiers)
